-- CANDIDATE release file generated by Worker AF (H8) from the tested Stage 2 combined candidate.
-- NOT committed, NOT installed anywhere. Source pieces and hashes: h8/RELEASE_FORM_RESULT.json.
-- Probe/prototype identifiers renamed to production names per h8/tools/rename_map.json.
-- Policy X: no economic-key derivation, freshness or post-Draft behaviour change beyond the tested winners.
-- Repeatable CloudTMS function authority: banking_pay_stage2_financial_readers_v1
-- Work-reference columns maintenance, bounded financial readers (A3/A7/A9/A12), settled/entitlement scope helpers,
-- advance clock (G06) and advance refresh. Groups G04/G05/G06 of COMBINED_CANDIDATE.json.

\set ON_ERROR_STOP on

begin;

-- [NEW] private.bpay_clock_changed_v1()  winner piece A1_EXTRACT  (tested name private.bpay_clock_changed_probe)
CREATE OR REPLACE FUNCTION private.bpay_clock_changed_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN PERFORM private.bpay_clock_rebuild_v1(OLD.timesheet_id);
 ELSIF TG_OP='INSERT' THEN PERFORM private.bpay_clock_rebuild_v1(NEW.timesheet_id);
 ELSE
  IF OLD.timesheet_id IS DISTINCT FROM NEW.timesheet_id THEN
   PERFORM private.bpay_clock_rebuild_v1(OLD.timesheet_id);
  END IF;
  PERFORM private.bpay_clock_rebuild_v1(NEW.timesheet_id);
 END IF;
 RETURN NULL;
END;
$function$;

-- [NEW] private.bpay_clock_override_changed_v1()  winner piece A1_EXTRACT  (tested name private.bpay_clock_override_changed_probe)
CREATE OR REPLACE FUNCTION private.bpay_clock_override_changed_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 NEW.bpay_clock_family_id_v1:=NULL;
 IF NEW.bpay_work_key_v1 IS NOT NULL THEN
  SELECT id INTO NEW.bpay_clock_family_id_v1 FROM private.bpay_clock_families_v1
  WHERE booking_id=NEW.bpay_work_key_v1;
  IF NEW.bpay_clock_family_id_v1 IS NULL THEN
   INSERT INTO private.bpay_clock_families_v1(booking_id) VALUES(NEW.bpay_work_key_v1)
   ON CONFLICT(booking_id) DO UPDATE SET booking_id=excluded.booking_id
   RETURNING id INTO NEW.bpay_clock_family_id_v1;
  END IF;
 END IF;
 RETURN NEW;
END;
$function$;

-- [NEW] private.bpay_clock_rebuild_v1(p_id uuid)  winner piece A1_EXTRACT  (tested name private.bpay_clock_rebuild_probe)
CREATE OR REPLACE FUNCTION private.bpay_clock_rebuild_v1(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE t public.timesheets%rowtype; f uuid; financial_at timestamptz; consumed timestamptz;
BEGIN
 SELECT * INTO t FROM public.timesheets WHERE timesheet_id=p_id FOR NO KEY UPDATE;
 IF NOT FOUND OR t.booking_id IS NULL OR btrim(t.booking_id)='' THEN
  DELETE FROM private.bpay_clock_rows_v1 WHERE timesheet_id=p_id; RETURN;
 END IF;
 SELECT id INTO f FROM private.bpay_clock_families_v1 WHERE booking_id=t.booking_id;
 IF f IS NULL THEN
  INSERT INTO private.bpay_clock_families_v1(booking_id) VALUES(t.booking_id)
  ON CONFLICT(booking_id) DO UPDATE SET booking_id=excluded.booking_id RETURNING id INTO f;
 END IF;
 SELECT authorised_at_utc INTO financial_at FROM public.timesheets_financials
 WHERE timesheet_id=p_id ORDER BY authorised_at_utc DESC NULLS LAST LIMIT 1;
 SELECT advance_authorisation_consumed_at_utc INTO consumed
 FROM public.timesheet_summary_pay_state_cache WHERE timesheet_id=p_id;
 INSERT INTO private.bpay_clock_rows_v1 VALUES(p_id,f,greatest(t.authorised_at_server,t.revoked_at,financial_at),consumed)
 ON CONFLICT(timesheet_id) DO UPDATE SET family_id=excluded.family_id,
 authorisation_at=excluded.authorisation_at,consumed_at=excluded.consumed_at;
END;
$function$;

-- [NEW] private.bpay_clock_retire_family_v1(p_family uuid)  winner piece A2  (tested name private.bpay_clock_retire_family_probe)
CREATE OR REPLACE FUNCTION private.bpay_clock_retire_family_v1(p_family uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private,pg_temp AS $fn$
BEGIN
-- Serialize last-reference checks. Without this, two concurrent removals can
-- each see the other's old reference and both leave an orphan directory row.
PERFORM 1 FROM private.bpay_clock_families_v1 WHERE id=p_family FOR UPDATE;
IF NOT FOUND THEN RETURN; END IF;
DELETE FROM private.bpay_clock_families_v1 f WHERE f.id=p_family
 AND NOT EXISTS(SELECT 1 FROM private.bpay_clock_rows_v1 c WHERE c.family_id=f.id)
 AND NOT EXISTS(SELECT 1 FROM public.timesheet_payment_overrides o WHERE o.bpay_clock_family_id_v1=f.id);
END;
$fn$;

-- [NEW] private.bpay_clock_retirement_changed_v1()  winner piece A1_EXTRACT  (tested name private.bpay_clock_retirement_changed_probe)
CREATE OR REPLACE FUNCTION private.bpay_clock_retirement_changed_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE f uuid;
BEGIN
 IF TG_TABLE_SCHEMA='private' THEN f:=OLD.family_id;
 ELSE f:=OLD.bpay_clock_family_id_v1; END IF;
 PERFORM private.bpay_clock_retire_family_v1(f); RETURN NULL;
END;
$function$;

-- [NEW] private.bpay_entitlement_financial_scope_v1(p_timesheet_ids uuid[])  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private.bpay_entitlement_financial_scope_v1(p_timesheet_ids uuid[])
 RETURNS TABLE(requested_timesheet_id uuid, booking_id text, canonical_timesheet_id uuid, family_timesheet_id uuid, family_is_current boolean, family_version integer, requested_is_canonical boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
WITH requested AS (
 SELECT DISTINCT t.timesheet_id,t.booking_id,t.bpay_work_key_v1
 FROM unnest(coalesce(p_timesheet_ids,'{}'::uuid[])) i(id)
 JOIN public.timesheets t ON t.timesheet_id=i.id
), roots AS (
 SELECT r.*, c.timesheet_id AS current_id
 FROM requested r
 LEFT JOIN public.timesheets c ON c.booking_id=r.booking_id AND c.is_current
 WHERE r.booking_id IS NOT NULL AND btrim(r.booking_id)<>''
), relevant AS (
 SELECT r.timesheet_id,r.booking_id,r.current_id,x.physical_id
 FROM roots r CROSS JOIN LATERAL (
   SELECT r.timesheet_id AS physical_id
   UNION SELECT r.current_id WHERE r.current_id IS NOT NULL
   UNION SELECT i.bpay_direct_source_timesheet_id_v1
     FROM public.pay_batch_items i WHERE i.bpay_direct_work_key_v1=r.bpay_work_key_v1
   UNION SELECT c.linked_timesheet_id
     FROM public.pay_finance_case_components c WHERE c.bpay_work_key_v1=r.bpay_work_key_v1
   UNION SELECT a.timesheet_id FROM public.ts_pay_adjustments a
     WHERE a.bpay_work_key_v1=r.bpay_work_key_v1 AND a.as_advance=false
   UNION SELECT s.timesheet_id FROM public.timesheet_pay_state s
     WHERE s.bpay_work_key_v1=r.bpay_work_key_v1
 ) x
)
SELECT r.timesheet_id,r.booking_id,r.current_id,t.timesheet_id,t.is_current,t.version,
 coalesce(r.timesheet_id=r.current_id,false)
FROM relevant r JOIN public.timesheets t ON t.timesheet_id=r.physical_id
UNION ALL
SELECT i.id,NULL::text,i.id,i.id,NULL::boolean,NULL::integer,false
FROM (SELECT DISTINCT id FROM unnest(coalesce(p_timesheet_ids,'{}'::uuid[])) i(id) WHERE id IS NOT NULL) i
WHERE NOT EXISTS(SELECT 1 FROM public.timesheets t WHERE t.timesheet_id=i.id);
$function$;

-- [NEW] private.bpay_finance_component_work_reference_v1()  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private.bpay_finance_component_work_reference_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
  NEW.bpay_work_key_v1:=NULL;
  NEW.bpay_work_revision_v1:=NULL;
  IF NEW.linked_timesheet_id IS NOT NULL THEN
    SELECT t.bpay_work_key_v1,t.bpay_work_revision_v1
      INTO STRICT NEW.bpay_work_key_v1,NEW.bpay_work_revision_v1
      FROM public.timesheets t WHERE t.timesheet_id=NEW.linked_timesheet_id;
  END IF;
  RETURN NEW;
END;
$function$;

-- [NEW] private.bpay_has_uncleared_advance_v1(p_timesheet_id uuid)  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private.bpay_has_uncleared_advance_v1(p_timesheet_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
SELECT EXISTS(SELECT 1 FROM public.timesheets t JOIN public.timesheet_payment_overrides o
 ON o.bpay_work_key_v1=t.bpay_work_key_v1 WHERE t.timesheet_id=p_timesheet_id
 AND o.cleared_at_utc IS NULL AND upper(btrim(coalesce(o.override_type,'')))='ADVANCE_THIS_PAYMENT');
$function$;

-- [NEW] private.bpay_item_work_reference_v1()  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private.bpay_item_work_reference_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE v_ref uuid; v_frozen text;
BEGIN
  -- Identical precedence to the retained finance-item source CASE expression.
  -- A component fallback stays indirect: changing the component never causes
  -- an unbounded fan-out rewrite of all referencing items.
  v_ref:=NEW.timesheet_id;
  IF v_ref IS NULL THEN
    v_frozen:=nullif(btrim(coalesce(NEW.frozen_source_basis_json->>'timesheet_id','')),'');
    IF v_frozen ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_ref:=v_frozen::uuid;
    END IF;
  END IF;
  NEW.bpay_direct_source_timesheet_id_v1:=v_ref;
  NEW.bpay_direct_work_key_v1:=NULL;
  NEW.bpay_direct_work_revision_v1:=NULL;
  IF v_ref IS NOT NULL THEN
    -- [Worker CA amendment ORPHAN-V5] A recorded reference whose Timesheet row no longer exists (deleted Timesheet;
    -- also seen transiently while a Timesheet delete cascades) keeps the exact recorded UUID with key and revision
    -- NULL. The retired CASE mapped such an item to that UUID too, so it matches no live family and is never a
    -- component fallback. Nothing is invented.
    SELECT t.bpay_work_key_v1,t.bpay_work_revision_v1
      INTO NEW.bpay_direct_work_key_v1,NEW.bpay_direct_work_revision_v1
      FROM public.timesheets t WHERE t.timesheet_id=v_ref;
  END IF;
  RETURN NEW;
END;
$function$;

