-- [NEW] private.bpay_timesheet_work_revision_v1()  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private.bpay_timesheet_work_revision_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN NEW.bpay_work_revision_v1:=0;
 ELSE NEW.bpay_work_revision_v1:=OLD.bpay_work_revision_v1+
   CASE WHEN NEW.booking_id IS DISTINCT FROM OLD.booking_id THEN 1 ELSE 0 END;
 END IF;
 RETURN NEW;
END;
$function$;

